class PurchaseRequestCreateRequest(Strict):
    requested_for_store_id:UUID|None=None; requested_for_warehouse_id:UUID|None=None; preferred_supplier_id:UUID|None=None; priority:Priority=Priority.NORMAL; required_by_date:date|None=None; reason:str=Field(min_length=2); remarks:str|None=None; items:list[PRItemRequest]=Field(min_length=1)
    @model_validator(mode="after")
    def loc(self):
        if (self.requested_for_store_id is None)==(self.requested_for_warehouse_id is None): raise ValueError("Exactly one destination is required")
        return self
